<script setup lang="ts">
import { ref } from 'vue'
import { ArrowRight, LockKeyhole, ShieldCheck } from 'lucide-vue-next'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth.store'
import { usersMock, roleLabels } from '../mocks/users'
import type { UserRole } from '../types'

const router = useRouter(); const authStore = useAuthStore()
const email = ref('operador@alerta.bo'); const password = ref('demo123'); const error = ref('')
const homes: Record<UserRole,string> = { CENTRAL_OPERATOR:'/central/dashboard', INSTITUTION_ADMIN:'/admin-institucion/dashboard', INSTITUTION_USER:'/institucion/dashboard', CITIZEN:'/ciudadano/inicio' }
const login = async()=>{error.value='';const user=await authStore.loginDemo(email.value);if(!user){error.value='Cuenta demo no reconocida.';return}await router.push(homes[user.rol])}
const useAccount=(accountEmail:string)=>{email.value=accountEmail;password.value='demo123'}
</script>
